@import url('https://fonts.googleapis.com/css2?family=Open+Sans:wght@300;400;600;700&display=swap');

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #000000;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;
  font-family: 'Open Sans', sans-serif;
  --h1-font-size: 48px;
  --h2-font-size: 36px;
  --h3-font-size: 32px;
  --h4-font-size: 28px;
  --h5-font-size: 24px;
  --h6-font-size: 22px;
  --p-font-size: 18px;
  --menu-font-size: 16px;
  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  color: var(--vt-ink);
  background: var(--vt-surface);
}

.root p {
  color: var(--vt-ink-soft);
  font-size: var(--p-font-size);
  font-weight: var(--font-weight-light);
  letter-spacing: 0.5px;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: all 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  font-weight: var(--font-weight-semibold);
}

.root h1,
.root h2 {
  font-weight: var(--font-weight-bold);
}

.root h1 {
  font-size: var(--h1-font-size);
  line-height: normal;
}

.root h2 {
  font-size: var(--h2-font-size);
}

.root h3 {
  font-size: var(--h3-font-size);
}

.root h4 {
  font-size: var(--h4-font-size);
}

.root h5 {
  font-size: var(--h5-font-size);
}

.root h6 {
  font-size: var(--h6-font-size);
}

.root .nav {
  padding-top: 20px;
  padding-bottom: 20px;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,.15);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
}

.root .navIn {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1rem;
}

.root .logo {
  display: inline-block;
}

.root .brand {
  color: var(--vt-accent);
  font-size: var(--h5-font-size);
  font-weight: var(--font-weight-bold);
  text-align: center;
}

.root .navLinks {
  display: flex;
  gap: 1.5rem;
}

.root .navLinks a {
  color: var(--vt-ink-soft);
  font-weight: var(--font-weight-semibold);
  font-size: var(--menu-font-size);
  padding: 0.5rem 1rem;
}

.root .navLinks a:hover,
.root .navLinks a:focus {
  color: var(--vt-ink);
}

.root .hero {
  padding-top: 0;
  margin-top: 94px;
}

.root .heroContainer {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.root .heroSlider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
}

.root .heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.root .heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.root .heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
}

.root .heroTitle {
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
}

.root .heroSubtitle {
  margin-bottom: 1.5rem;
}

.root .customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: var(--font-weight-semibold);
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
}

.root .customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  text-align: center;
  transition: all 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.root .customLink:hover::before {
  top: 0;
}

.root .contactPhone {
  font-weight: var(--font-weight-semibold);
  margin-left: 1rem;
}

.root .section {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.root .container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

.root .aboutRow {
  display: flex;
  flex-wrap: wrap;
}

.root .aboutCol {
  flex: 1 1 auto;
}

.root .aboutTitle {
  margin-bottom: 1rem;
}

.root .aboutText {
  margin-bottom: 1rem;
}

.root .gallerySection {
  padding: 0;
}

.root .galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.root .galleryCol {
  flex: 0 0 50%;
}

.root .galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.root .timelineSection {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.root .sectionTitle {
  text-align: center;
  margin-bottom: 3rem;
}

.root .timeline {
  position: relative;
}

.root .timeline::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  transform: translateX(-50%);
}

.root .timelineNode {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  position: relative;
  margin-bottom: 2rem;
}

.root .timelineNode.odd {
  flex-direction: row;
}

.root .timelineNode.even {
  flex-direction: row-reverse;
}

.root .timelineContent {
  width: 45%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,.15);
  border-radius: 0 0 0.25rem 0.25rem;
}

.root .timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 20px;
  border-radius: 0.25rem 0.25rem 0 0;
  margin: 0;
  position: relative;
}

.root .timelineNode.odd .timelineTitle::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.root .timelineNode.even .timelineTitle::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.root .timelineDesc,
.root .timelineDuration,
.root .timelinePrice {
  padding: 10px 20px;
  margin: 0;
}

.root .timelineDuration,
.root .timelinePrice {
  font-weight: var(--font-weight-semibold);
  color: var(--vt-ink);
}

.root .timelineIcon {
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0,0,0,.175);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  position: relative;
}

.root .timelineNumber {
  color: var(--vt-accent);
  font-size: var(--h3-font-size);
  font-weight: var(--font-weight-bold);
}

.root .timelineDate {
  width: 45%;
  /* empty spacer */
}

.root .footer {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.root .footerRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
}

.root .footerColHours,
.root .footerColClinic,
.root .footerColSocial {
  flex: 1;
  min-width: 200px;
  margin-right: 2rem;
}

.root .footerColCopyright {
  flex-basis: 100%;
  margin-top: 2rem;
  text-align: center;
}

.root .footerTitle {
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.root .footerText {
  margin-bottom: 0.5rem;
}

.root .copyrightText {
  font-size: var(--menu-font-size);
  color: var(--vt-ink-soft);
}

@media screen and (max-width: 991px) {
  .root .navIn {
    flex-direction: column;
  }

  .root .navLinks {
    margin-top: 1rem;
    flex-wrap: wrap;
    justify-content: center;
  }

  .root .heroContainer {
    height: auto;
  }

  .root .heroText {
    position: relative;
    bottom: 0;
    right: 0;
    width: auto;
    padding: 2rem;
    margin-top: -100px;
    background: var(--vt-surface);
  }

  .root .timeline::before {
    left: 40px;
  }

  .root .timelineNode.odd,
  .root .timelineNode.even {
    flex-direction: column;
    align-items: flex-start;
  }

  .root .timelineContent {
    width: auto;
    margin-left: 80px;
  }

  .root .timelineIcon {
    position: absolute;
    left: 0;
    top: 0;
  }

  .root .timelineDate {
    display: none;
  }

  .root .footerColHours,
  .root .footerColClinic,
  .root .footerColSocial {
    flex-basis: 100%;
    margin-right: 0;
    margin-bottom: 2rem;
  }
}

@media screen and (max-width: 575px) {
  .root .heroText {
    padding: 1rem;
  }

  .root .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 20px;
  }

  .root .contactPhone {
    font-size: 12px;
  }

  .root .timeline::before {
    left: 30px;
  }

  .root .timelineContent {
    margin-left: 70px;
  }

  .root .timelineIcon {
    width: 70px;
    height: 70px;
  }

  .root .timelineNumber {
    font-size: var(--h6-font-size);
  }
}

@media (prefers-reduced-motion: reduce) {
  .root .heroSlider {
    scroll-behavior: auto;
  }
}
